fn perimeter(shape: (u32, u32)) -> u32 {
    2 * (shape.0 + shape.1)
}

fn perimeter(shape: (u32, u32, u32)) -> u32 {
    let a = shape.0;
    let b = shape.1;
    let c = shape.2;

    if a == b && b == c {
        3 * a
    } else {
        2 * (a + b + c)
    }
}

